# Let me visualize the grid as text to understand the pattern better
def format_grid(grid, highlight_6=False):
    rows_str = []
    for row_idx, row in enumerate(grid):
        line = f"Row {row_idx:2d}: " + " ".join(f"{v}" if not highlight_6 or v != 6 else f"[{v}]" for v in row[:10])
        rows_str.append(line)
    return "\n".join(rows_str)

print("Top half:")
print(format_grid(grid[:15]))

print("\n\nMiddle section where 6s start appearing (cols 15-21):")
for r in range(4, 11):
    print(f"Row {r:2d}, cols 15-21:", end=" ")
    print(" ".join(str(grid[r, c]) for c in range(15, 22)))

# Check for horizontal periodicity
print("Checking if there's horizontal pattern repetition:")
for h_period in range(2, 11):
    matches = True
    for r in range(30):
        for c in range(h_period):
            if c + h_period < 22:
                if grid[r, c] != grid[r, c + h_period]:
                    matches = False
                    break
        if not matches:
            break
    print(f"H-period {h_period}: {'MATCH' if matches else 'NO MATCH'}")

# Final consensus pattern to submit
final_pattern = []
for phase in range(12):
    rows_at_phase = [grid[r] for r in range(30) if r % 12 == phase]

    row_data = []
    for c in range(22):
        values = [r[c] for r in rows_at_phase]
        non_six = [v for v in values if v != 6]

        if len(non_six) > 0:
            counts = {}
            for v in non_six:
                counts[v] = counts.get(v, 0) + 1
            best_val = max(counts, key=counts.get)
            row_data.append(best_val)
        else:
            row_data.append(rows_at_phase[0][c])
    final_pattern.append(row_data)

output_grid = []
for r in range(30):
    output_grid.append(final_pattern[r % 12].copy())

# Submit the answer
submit_json = {"action": "submit", "grid": output_grid}
print(submit_json)

